"""Run actual report JS and exercise time, optimization and case selection."""
import argparse,html,json,re,subprocess,tempfile
from pathlib import Path
def main():
    p=argparse.ArgumentParser();p.add_argument('report',type=Path);a=p.parse_args();a.report=a.report.resolve();out=a.report.parent
    script='''<script>try{let c=document.getElementById('map'),s=document.getElementById('time'),m=document.getElementById('mode'),sel=document.getElementById('case'),before=c.toDataURL();s.value=35;s.dispatchEvent(new Event('input'));let checks={rendered:window.s06Rendered===true,time_changes_map:before!==c.toDataURL(),measured_points_present:Object.values(data).every(d=>d.points.length>100),nonzero_height:Object.values(data).some(d=>d.points.some(p=>p[2]>2))};s.value=100;s.dispatchEvent(new Event('input'));before=c.toDataURL();m.value='raw';m.dispatchEvent(new Event('change'));checks.before_after_changes_map=before!==c.toDataURL();if(sel.options.length>1){before=c.toDataURL();sel.selectedIndex=sel.options.length-1;sel.dispatchEvent(new Event('change'));checks.case_changes_map=before!==c.toDataURL();}sel.selectedIndex=0;m.value='optimized';sel.dispatchEvent(new Event('change'));checks.passed=Object.values(checks).every(Boolean);let p=document.createElement('pre');p.id='s06_qa_result';p.textContent=JSON.stringify(checks);document.body.append(p);}catch(e){let p=document.createElement('pre');p.id='s06_qa_result';p.textContent=JSON.stringify({passed:false,error:String(e)});document.body.append(p);}</script>'''
    with tempfile.TemporaryDirectory(prefix='s06_report_') as tmp:
        tmp=Path(tmp);page=tmp/'qa.html';page.write_text(a.report.read_text().replace('<meta charset="utf-8">','<meta charset="utf-8"><base href="'+out.as_uri()+'/">').replace('</html>',script+'</html>'))
        args=['google-chrome','--headless','--disable-gpu','--no-first-run','--no-default-browser-check',f'--user-data-dir={tmp}/profile','--virtual-time-budget=3000','--window-size=1480,1200',f'--screenshot={out}/report_preview.png','--dump-dom',page.as_uri()]
        r=subprocess.run(args,capture_output=True,text=True,timeout=40);match=re.search(r'<pre id="s06_qa_result">(.*?)</pre>',r.stdout);result=json.loads(html.unescape(match.group(1))) if match else dict(passed=False,error='QA DOM missing',exit_code=r.returncode)
        result.update(command=args,exit_code=r.returncode);(out/'browser_check.json').write_text(json.dumps(result,indent=2)+'\n');print(json.dumps(result));return 0 if result.get('passed') and not r.returncode else 1
if __name__=='__main__':raise SystemExit(main())
